C335_R = [('        for (const row of grid) row.fill(-1); carve(0, -1, 0, 0);', "        { const half = (t) => Math.random() < 0.5 ? Math.ceil(t / 2) : Math.ceil(t * 0.6);   // c335: 길고 좁은 칸막이 공간 없애기 — 벽을 옮겨 5:5 또는 6:4로 나눈다\n          for (const a of rooms) for (const b of rooms) { if (a === b || sec(a.c) !== sec(b.c)) continue;   // 맞붙은 두 방 중 하나가 2칸 이하로 좁으면 둘 사이 벽을 가운데쯤으로\n            if (a.r === b.r && a.h === b.h && a.c + a.w === b.c) { const t = a.w + b.w; if (Math.min(a.w, b.w) <= 2 && Math.min(a.w, b.w) / t < 0.35) { const na = a.w > b.w ? half(t) : t - half(t); a.w = na; b.c = a.c + na; b.w = t - na; } }\n            if (a.c === b.c && a.w === b.w && a.r + a.h === b.r) { const t = a.h + b.h; if (Math.min(a.h, b.h) <= 2 && Math.min(a.h, b.h) / t < 0.35) { const na = a.h > b.h ? half(t) : t - half(t); a.h = na; b.r = a.r + na; b.h = t - na; } } }\n          const roomAtC = (cc, rr) => rooms.some((q) => cc >= q.c && cc < q.c + q.w && rr >= q.r && rr < q.r + q.h);\n          for (const q of rooms) for (const sd of ['n', 's', 'w', 'e']) {   // 방과 벽(구간 테두리·다른 방) 사이 한 칸짜리 좁은 틈 — 방 벽을 옮겨 틈과 방을 반쯤으로\n            const hz = sd === 'n' || sd === 's', T = hz ? q.h : q.w; if (T < 3) continue; let g = 0;\n            for (let k = 1; k <= 2; k++) { const lineFree = hz ? Array.from({ length: q.w }, (_, i) => q.c + i).every((cc) => { const rr = sd === 'n' ? q.r - k : q.r + q.h - 1 + k; return rr >= 0 && rr < NR && !roomAtC(cc, rr); }) : Array.from({ length: q.h }, (_, i) => q.r + i).every((rr) => { const cc = sd === 'w' ? q.c - k : q.c + q.w - 1 + k; return cc >= 0 && cc < NC && sec(cc) === sec(q.c) && !roomAtC(cc, rr); }); if (!lineFree) break; g = k; }\n            if (g !== 1) continue; const nt = T + g - half(T + g) < 2 ? T : half(T + g), d = T - nt; if (d <= 0) continue;\n            if (sd === 'n') { q.r += d; q.h -= d; } else if (sd === 's') q.h -= d; else if (sd === 'w') { q.c += d; q.w -= d; } else q.w -= d; } }\n        for (const row of grid) row.fill(-1); carve(0, -1, 0, 0);"), ('    const LX = (Q.x0 + Q.x1) / 2, R1 = Q.z1, R0 = Q.z0, obst', "    for (const zf of [0.68, 0.3]) { const z = P.z0 + (P.z1 - P.z0) * zf, cx = (P.x0 + P.x1) / 2 + (zf > 0.5 ? -1.5 : 1.5), ob = (bar, x) => { const c = chParked(x, z, 0, bar); c.tutS = P; };   // c335: 주차장 중간중간 작은 진지 둘 — 경찰차 하나 + 바리케이트 둘 (틈 있게), 그 뒤에 경찰 2 · 군인 2 (저격수 없음)\n      ob(true, cx - 5.2); ob(false, cx); ob(true, cx + 5.2);\n      for (const [t, dx] of [['police', -3.6], ['soldier', -1.2], ['soldier', 1.2], ['police', 3.6]]) { const c = man(P, t, cx + dx, z - 2.2); c.post = c.area; if (t === 'soldier') c.noMaster = true; enterNormal(c); } }\n    const LX = (Q.x0 + Q.x1) / 2, R1 = Q.z1, R0 = Q.z0, obst"), ('if (w >= 2 && sec(cc) === sec(cc + w - 1)) cand.push', 'if (w >= 2 && Math.max(w, h) <= 2 * Math.min(w, h) && sec(cc) === sec(cc + w - 1)) cand.push'), ('const o = rooms.find((p) => p !== q && !p.gone && sec(p.c) === sec(q.c) && ((p.r === q.r && p.h === q.h && (p.c + p.w === q.c || q.c + q.w === p.c)) || (p.c === q.c && p.w === q.w && (p.r + p.h === q.r || q.r + q.h === p.r))));', 'const o = rooms.find((p) => p !== q && !p.gone && sec(p.c) === sec(q.c) && ((p.r === q.r && p.h === q.h && (p.c + p.w === q.c || q.c + q.w === p.c) && Math.max(p.w + q.w, p.h) <= 2.5 * Math.min(p.w + q.w, p.h)) || (p.c === q.c && p.w === q.w && (p.r + p.h === q.r || q.r + q.h === p.r) && Math.max(p.h + q.h, p.w) <= 2.5 * Math.min(p.h + q.h, p.w))));   /* c335: 합쳐서 길쭉해지면 안 합친다 */')]
